import { useCallback, useEffect, useState } from "react";
import { DateHelper, LocalStorageHelper } from "../helpers";
import dayjs from "dayjs";
import { DateSource } from "../helpers/date-helper";

/**
 * Used to keep state in the localStorage
 * @param key The key to keep in the localStorage
 * @param initialValue The initial value to set if the key does not exist in localStorage. The state also gets this initial value when the expiration of the entry is reached.
 *
 * @returns An array with the localStorage value and a function to update it
 *
 * To update the value with an expiration date, pass the expiration as the second argument to `updateLocalStorage`.
 * The expiration can either be a duration like `dayjs.duration(5, "minutes")` or a point in time like `new Date("2024-05-05T00:00:00")`.
 */
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [localStorageValue, setLocalStorageValue] = useState<T>(() => {
    const value: T = LocalStorageHelper.getItem(key);
    return value !== undefined ? value : initialValue;
  });

  const updateLocalStorage = useCallback(
    (newValue: T | undefined, expiration?: plugin.Duration | DateSource) => {
      if (newValue === undefined) {
        LocalStorageHelper.removeItem(key);
        setLocalStorageValue(initialValue);
      } else {
        const timestampExpiration = dayjs.isDuration(expiration) ? dayjs().add(expiration) : expiration;
        LocalStorageHelper.setItem(key, newValue, timestampExpiration);
        setLocalStorageValue(newValue);
      }
    },
    [key, initialValue],
  );

  /**This use effect will depend on `localStorageValue`. When there is a new value in the state, check if that comes with a expiration.
   * If there is an expiration, set a timeout to remove the item from the localStorage, and update the state, when the expiration is reached.
   */
  useEffect(() => {
    const maybeExpirationInLocalStorage = LocalStorageHelper.getValidUntilTimeStamp(key);
    if (!maybeExpirationInLocalStorage) return undefined;

    const durationUntilExpiration = DateHelper.millisecondsUntilDate(dayjs(maybeExpirationInLocalStorage));
    if (durationUntilExpiration <= 0) return undefined;

    const timoutId = window.setTimeout(() => {
      updateLocalStorage(undefined);
    }, durationUntilExpiration);

    return () => {
      clearTimeout(timoutId);
    };
  }, [localStorageValue, key, updateLocalStorage]);

  return [localStorageValue, updateLocalStorage] as const;
}
