import { useLocalStorage } from "@/core/hooks";
import { IDigitalRideMediaService } from "@/core/services";
import { useQueries } from "@tanstack/react-query";
import { isNonEmptyArray, multipleClassNames } from "@/core/helpers";
import structure from "@/core/styling/structure.module.less";
import { ExistingAlbumsList } from "../elements/existing-albums-list/existing-albums-list";
import { SearchAlbumForm } from "../elements";
import styles from "./digital-ride-media-start-block.module.less";
import { useTranslation } from "react-i18next";
import HeroBlock, { Props as HeroBlockProps } from "@/core/components/blocks/hero-block/hero-block";
import { IGatsbyImageData } from "gatsby-plugin-image";
import Carousel from "@/core/components/primitives/carousel/carousel";
import RestaurantListItem from "@/core/components/primitives/restaurant-list-item/restaurant-list-item";
import RichText, { LinkReference, RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import ExpandContent from "@/core/components/primitives/expand-content/expand-content";
import { Fragment } from "react/jsx-runtime";
import { OutlineButtonLink } from "@/core/components/primitives/parks-button/parks-button";
import { TextBlock, Props as TextBlockProps } from "@/core/components/primitives/text-block/text-block";
import Card from "@/core/components/primitives/card/card";

type HowToCards = Array<{
  image: IGatsbyImageData;
  heading: string;
  paragraph: string;
}>;

type QuestionsAndAnswers = Array<{
  question: string;
  answer: RichTextType;
}>;

type Props = {
  service: IDigitalRideMediaService;
  navigateToAlbum: (albumId: string) => void;
  helpPageLink: LinkReference;
  heroBlock?: HeroBlockProps;
  howToCards?: HowToCards;
  questionsAndAnswers?: QuestionsAndAnswers;
  informationBanner?: Pick<TextBlockProps, "title" | "richText">;
  textBlocks?: TextBlockProps[];
};

const DigitalRideMediaStartBlock = ({
  service,
  navigateToAlbum,
  helpPageLink,
  heroBlock,
  howToCards,
  questionsAndAnswers,
  informationBanner,
  textBlocks,
}: Props) => {
  const [savedAlbumsIds] = useLocalStorage<Array<string>>("savedRideMediaAlbumIds", []);
  const albumsMetadataQueries = useQueries({
    queries: savedAlbumsIds.map((albumId) => {
      // eslint-disable-next-line @tanstack/query/exhaustive-deps
      return {
        queryKey: ["album-metadata", albumId],
        queryFn: () => service.fetchAlbum(albumId),
      };
    }),
  });

  const { t } = useTranslation();

  return (
    <>
      {heroBlock && <HeroBlock {...heroBlock} />}
      <section className={multipleClassNames(styles.wrapper, structure.block, structure.blockMaxWidthM)}>
        {isNonEmptyArray(howToCards) && savedAlbumsIds.length === 0 && (
          <HowToSection howToCards={howToCards} informationBanner={informationBanner} />
        )}
        {savedAlbumsIds.length > 0 && (
          <>
            <div className={styles.introText}>
              <h2>{t("rideMediaStartPageHeading")}</h2>
              <p>{t("rideMediaStartPageParagraph")}</p>
            </div>
            <ExistingAlbumsList
              albums={savedAlbumsIds.map((id, index) => ({ id, query: albumsMetadataQueries[index] }))}
              action="GO_TO_ALBUM"
              onClick={navigateToAlbum}
            />
          </>
        )}
        {isNonEmptyArray(textBlocks) && (
          <div>
            {textBlocks.map((block, index) => (
              <TextBlock key={index} {...block} />
            ))}
          </div>
        )}
        <div className={styles.searchAlbumForm}>
          <h2>{t("rideMediaStartPageSearchForAlbumHeading")}</h2>
          <SearchAlbumForm
            service={service}
            albumAction={{ action: "GO_TO_ALBUM" }}
            onClickAlbumResult={navigateToAlbum}
          />
        </div>
        {isNonEmptyArray(howToCards) && savedAlbumsIds.length > 0 && (
          //Don't show information banner if we have saved albums
          <HowToSection howToCards={howToCards} informationBanner={undefined} />
        )}
        <OutlineButtonLink
          label={helpPageLink.title}
          url={helpPageLink.internalLink?.slug ?? helpPageLink.externalUrl}
        />
        {isNonEmptyArray(questionsAndAnswers) && (
          <div className={styles.faqSection}>
            <h2>{t("rideMediaStartPageFAQHeading")}</h2>
            {questionsAndAnswers.map((qa, index) => (
              <Fragment key={index}>
                <div className={styles.faqItem} data-is-first={index === 0}>
                  <ExpandContent
                    buttonType="plain"
                    buttonPosition="top"
                    showMoreLabelOverride={qa.question}
                    showLessLabelOverride={qa.question}
                  >
                    <div className={styles.answerWrapper}>
                      <RichText richText={qa.answer} />
                    </div>
                  </ExpandContent>
                </div>
                <hr />
              </Fragment>
            ))}
          </div>
        )}
      </section>
    </>
  );
};

const HowToSection = ({
  howToCards,
  informationBanner,
}: {
  howToCards: NonNullable<Props["howToCards"]>;
  informationBanner?: Props["informationBanner"];
}) => {
  const { t } = useTranslation();
  return (
    <div className={styles.howToCards}>
      {informationBanner && informationBanner.title && informationBanner.richText && (
        <Card className={styles.informationBanner}>
          <h2>{informationBanner.title}</h2>
          <RichText richText={informationBanner.richText} />
        </Card>
      )}
      <h2>{t("rideMediaStartPageHowToHeading")}</h2>
      <Carousel>
        {howToCards.map((card, index) => (
          //@ts-expect-error RestaurantListItem is somewhat of a hack to get a plain card with an image and text.
          //It actually expects more props, but omitting them doesn't seem to cause any runtime issues.
          //I could have modified the prop types and made more of them optional, but I would rather wait until there is a better generic card component
          //and not have to modify the RestaurantListItem component at all.
          <RestaurantListItem
            key={index}
            title={card.heading}
            bodyText={card.paragraph}
            image={card.image}
            labels={{}}
          />
        ))}
      </Carousel>
    </div>
  );
};

export default DigitalRideMediaStartBlock;
